//! Original PostgreSQL18.6 value codec correspondence, never native session/source authority.
use std::io::{Read,Write};use serde_json::json;use weft_core::error::{Diagnostic,Result};
fn fail()->Diagnostic{Diagnostic::new("WFT-SECURITY-CODEC-INPUT","input","Bounded original codec input required")}
fn run()->Result<String>{let mut bytes=Vec::new();std::io::stdin().take(16_000_001).read_to_end(&mut bytes).map_err(|_|fail())?;if bytes.len()>16_000_000{return Err(fail());}let v=weft_core::json::checked_json(std::str::from_utf8(&bytes).map_err(|_|fail())?).map_err(|_|fail())?;let o=v.as_object().ok_or_else(fail)?;if !o.contains_key("requestJson")||o.keys().any(|k|!matches!(k.as_str(),"requestJson"|"operandBatchJson")){return Err(fail());}let request=v["requestJson"].as_str().ok_or_else(fail)?;
 weft_core::security_mapping_transport::with_security_relationship_context(request,|ctx|{let source=serde_json::from_str(ctx.binding_json()).map_err(|_|fail())?;let checked=if let Some(batch)=v.get("operandBatchJson"){weft_postgresql::security_native_codecs::check_postgresql_operand_codecs(ctx,&source,batch.as_str().ok_or_else(fail)?)?}else{weft_postgresql::security_native_codecs::check_postgresql_parameter_codecs(ctx,&source)?};Ok(json!({"version":"weft.postgresql.codecs.inspected/0.1-candidate","securityReady":false,"contextSha256":checked.context_sha256(),"parameterCount":checked.parameter_count(),"operandCount":checked.operand_count(),"nativeSessionAdmission":"required"}).to_string()+"\n")})}
fn main(){match run(){Ok(v)=>{if std::io::stdout().write_all(v.as_bytes()).is_err(){std::process::exit(1)}},Err(d)=>{let _=writeln!(std::io::stderr(),"{}",serde_json::to_string(&d).unwrap());std::process::exit(1)}}}
